'AC-extraction.2009.2 AC20.9.1 EPIC-020'; from __future__ import annotations; from decimal import Decimal; from unittest.mock import AsyncMock, patch; from uuid import uuid4; import pytest; from sqlalchemy import select; from src.extraction import BankStatementStatus, DocumentSource; from src.extraction.extension._llm_led_gate import QUARANTINE_METRIC_KIND, LlmLedQuarantineReason, evaluate_llm_led_extraction_gate; from src.extraction.extension.service import ExtractionService; from src.extraction.orm.layer2 import AtomicTransaction; from src.extraction.orm.statement_summary import StatementSummary
